def mini_strip(s):
    # 生效条件：s 为字符串
    # 子功能：① 定位首个非空白；② 定位末个非空白；③ 切片返回
    # 执行：顺序扫描；切片
    # 不适用条件：只去首尾，不去中间空白；不用内建 strip
    ws = ' \t\n\r'
    start = 0
    while start < len(s) and s[start] in ws:
        start += 1
    end = len(s)
    while end > start and s[end - 1] in ws:
        end -= 1
    return s[start:end]

def mini_startswith(s, prefix):
    # 生效条件：s/prefix 均为字符串
    # 子功能：① 空前缀返 True；② 逐位比对前 len(prefix) 字符；③ 不匹配返 False
    # 执行：循环迭代；条件分派
    # 不适用条件：任意位置子串匹配（用 mini_contains）；不用内建 startswith
    if len(prefix) > len(s):
        return False
    for i in range(len(prefix)):
        if s[i] != prefix[i]:
            return False
    return True

def mini_endswith(s, suffix):
    # 生效条件：s/suffix 均为字符串
    # 子功能：① 空后缀返 True；② 从尾部对齐逐位比对；③ 不匹配返 False
    # 执行：循环迭代；条件分派
    # 不适用条件：多后缀元组形式不在本单元范围；不用内建 endswith
    if len(suffix) > len(s):
        return False
    offset = len(s) - len(suffix)
    for i in range(len(suffix)):
        if s[offset + i] != suffix[i]:
            return False
    return True
